#include <chrono>
#include <thread>

struct TenantConfig {
    std::string tenant_id;
    std::string allowed_domain;
    std::string data_dir;
    uint16_t port;
};

class DNSResolver {
public:
    struct CacheEntry {
        std::string ip;
        std::chrono::steady_clock::time_point resolved_at;
        uint32_t ttl_seconds;
    };

    std::string resolve(const std::string& hostname) {
        std::lock_guard<std::mutex> lock(cache_mutex_);
        auto it = cache_.find(hostname);
        if (it != cache_.end()) {
            auto elapsed = std::chrono::duration_cast<std::chrono::seconds>(
                std::chrono::steady_clock::now() - it->second.resolved_at).count();
            if (elapsed < it->second.ttl_seconds) {
                return it->second.ip;
            }
            cache_.erase(it);
        }
        return do_resolve(hostname);
    }

private:
    std::string do_resolve(const std::string& hostname) {
        struct addrinfo hints{}, *res;
        hints.ai_family = AF_INET;
        hints.ai_socktype = SOCK_STREAM;
        if (getaddrinfo(hostname.c_str(), nullptr, &hints, &res) != 0)
            return "";
        char ip[INET_ADDRSTRLEN];
        struct sockaddr_in* addr = (struct sockaddr_in*)res->ai_addr;
        inet_ntop(AF_INET, &addr->sin_addr, ip, sizeof(ip));
        CacheEntry entry{ip, std::chrono::steady_clock::now(), 300};
        cache_[hostname] = entry;
        freeaddrinfo(res);
        return ip;
    }

    std::map<std::string, CacheEntry> cache_;
    std::mutex cache_mutex_;
};

class FileProcessingService {
public:
    FileProcessingService(const std::vector<TenantConfig>& configs)
        : configs_(configs) {}

    bool validate_callback_origin(const std::string& tenant_id, const std::string& callback_host) {
        for (const auto& cfg : configs_) {
            if (cfg.tenant_id == tenant_id) {
                std::string resolved_ip = resolver_.resolve(callback_host);
                if (resolved_ip.empty()) return false;
                if (!is_public_ip(resolved_ip)) return false;
                if (!domain_matches(callback_host, cfg.allowed_domain)) return false;
                return true;
            }
        }
        return false;
    }

    bool process_file_with_callback(const std::string& tenant_id,
                                     const std::string& filename,
                                     const std::string& callback_host) {
        if (!validate_callback_origin(tenant_id, callback_host))
            return false;

        std::string filepath = get_tenant_dir(tenant_id) + "/" + sanitize_filename(filename);
        std::ifstream file(filepath);
        if (!file.is_open()) return false;

        std::string content((std::istreambuf_iterator<char>(file)),
                            std::istreambuf_iterator<char>());
        file.close();

        // Simulate processing delay
        std::this_thread::sleep_for(std::chrono::milliseconds(100));

        // Re-resolve for callback delivery - uses fresh DNS lookup
        std::string callback_ip = fresh_resolve(callback_host);
        if (callback_ip.empty()) return false;

        return deliver_result(callback_ip, get_tenant_port(tenant_id), content);
    }

private:
    std::string fresh_resolve(const std::string& hostname) {
        struct addrinfo hints{}, *res;
        hints.ai_family = AF_INET;
        hints.ai_socktype = SOCK_STREAM;
        if (getaddrinfo(hostname.c_str(), nullptr, &hints, &res) != 0)
            return "";
        char ip[INET_ADDRSTRLEN];
        struct sockaddr_in* addr = (struct sockaddr_in*)res->ai_addr;
        inet_ntop(AF_INET, &addr->sin_addr, ip, sizeof(ip));
        freeaddrinfo(res);
        return ip;
    }

    bool is_public_ip(const std::string& ip) {
        uint32_t addr;
        inet_pton(AF_INET, ip.c_str(), &addr);
        addr = ntohl(addr);
        // Block RFC1918 and loopback
        if ((addr & 0xFF000000) == 0x0A000000) return false; // 10.0.0.0/8
        if ((addr & 0xFFF00000) == 0xAC100000) return false; // 172.16.0.0/12
        if ((addr & 0xFFFF0000) == 0xC0A80000) return false; // 192.168.0.0/16
        if ((addr & 0xFF000000) == 0x7F000000) return false; // 127.0.0.0/8
        return true;
    }

    bool domain_matches(const std::string& host, const std::string& allowed) {
        if (host == allowed) return true;
        std::string suffix = "." + allowed;
        if (host.length() > suffix.length() &&
            host.compare(host.length() - suffix.length(), suffix.length(), suffix) == 0)
            return true;
        return false;
    }

    std::string sanitize_filename(const std::string& name) {
        std::string result;
        for (char c : name) {
            if (c == '/' || c == '\\' || c == '.' || c == '~') continue;
            if (std::isalnum(c) || c == '_' || c == '-') result += c;
        }
        return result;
    }

    std::string get_tenant_dir(const std::string& tenant_id) {
        for (const auto& cfg : configs_)
            if (cfg.tenant_id == tenant_id) return cfg.data_dir;
        return "";
    }

    uint16_t get_tenant_port(const std::string& tenant_id) {
        for (const auto& cfg : configs_)
            if (cfg.tenant_id == tenant_id) return cfg.port;
        return 0;
    }

    bool deliver_result(const std::string& ip, uint16_t port, const std::string& data) {
        int sock = socket(AF_INET, SOCK_STREAM, 0);
        if (sock < 0) return false;
        struct sockaddr_in addr{};
        addr.sin_family = AF_INET;
        addr.sin_port = htons(port);
        inet_pton(AF_INET, ip.c_str(), &addr.sin_addr);
        if (connect(sock, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
            close(sock);
            return false;
        }
        send(sock, data.c_str(), data.size(), 0);
        close(sock);
        return true;
    }

    std::vector<TenantConfig> configs_;
    DNSResolver resolver_;
};

